#!/usr/bin/env node
/**
 * Generates THIRD-PARTY-NOTICES.md from `cargo metadata`.
 *
 * Lists every third-party crate the release binaries link, with its SPDX
 * license expression, plus the distinct license texts (deduplicated) in an
 * appendix. License texts are read from the local cargo registry cache, so a
 * fresh checkout that has not built yet lists licenses by name and links
 * only. Commit the generated file; regenerate after dependency changes.
 */

import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(fileURLToPath(new URL('.', import.meta.url)), '..')
const out = join(root, 'THIRD-PARTY-NOTICES.md')

const meta = JSON.parse(
  execFileSync('cargo', ['metadata', '--format-version', '1'], {
    cwd: root,
    encoding: 'utf8',
    maxBuffer: 256 * 1024 * 1024,
  }),
)

const members = new Set(meta.workspace_members)
const crates = meta.packages.filter((p) => !members.has(p.id))

const srcRoots = readdirSync(join(homedir(), '.cargo', 'registry', 'src'))
  .map((name) => join(homedir(), '.cargo', 'registry', 'src', name))

const LICENSE_FILE = /^(license|licence|copying|unlicense)(-[a-z0-9]+)?(\.[a-z]+)?$/i

function licenseTexts(pkg) {
  const dir = srcRoots
    .map((src) => join(src, `${pkg.name}-${pkg.version}`))
    .find((d) => {
      try {
        return statSync(d).isDirectory()
      } catch {
        return false
      }
    })
  if (!dir) return []
  const texts = []
  const scan = (dirPath, prefix) => {
    for (const entry of readdirSync(dirPath, { withFileTypes: true }).sort((a, b) =>
      a.name.localeCompare(b.name),
    )) {
      if (entry.isDirectory()) {
        if (entry.name === 'LICENSES' || entry.name === 'licenses') scan(join(dirPath, entry.name), '')
        continue
      }
      const name = prefix ? `${prefix}${entry.name}` : entry.name
      if (!LICENSE_FILE.test(name)) continue
      try {
        const text = readFileSync(join(dirPath, entry.name), 'utf8').trim()
        if (text) texts.push({ name, text })
      } catch {
        // unreadable license file: the SPDX line still covers the crate
      }
    }
  }
  scan(dir, '')
  return texts
}

const seen = new Map()
const appendix = []
const cratesSorted = [...crates].sort((a, b) =>
  a.name === b.name ? a.version.localeCompare(b.version) : a.name.localeCompare(b.name),
)

const entries = cratesSorted.map((pkg) => {
  const spdx = (pkg.license ?? pkg.licenses ?? 'unknown').trim() || 'unknown'
  const texts = licenseTexts(pkg)
  const label = texts.length > 0 ? texts[0].text : ''
  const key = label ? createHash('sha256').update(label).digest('hex').slice(0, 12) : null
  let ref
  if (key && seen.has(key)) {
    ref = seen.get(key)
  } else if (key) {
    ref = `L${appendix.length + 1}`
    seen.set(key, ref)
    appendix.push({ id: ref, spdx, text: label, source: `${pkg.name} ${pkg.version} / ${texts[0].name}` })
  } else {
    ref = null
  }
  return { pkg, spdx, ref }
})

const lines = []
lines.push('# Third-party notices')
lines.push('')
lines.push(
  `The release binaries link ${entries.length} third-party crates. This file lists each one with its license; the distinct license texts are in the appendix.`,
)
lines.push('')
lines.push('Generated by `scripts/generate-third-party-notices.mjs` — run `node scripts/generate-third-party-notices.mjs` after dependency changes and commit the result.')
lines.push('')
lines.push('## Dependencies')
lines.push('')
lines.push('| Crate | Version | License | Text |')
lines.push('| --- | --- | --- | --- |')
for (const { pkg, spdx, ref } of entries) {
  lines.push(`| ${pkg.name} | ${pkg.version} | ${spdx} | ${ref ?? '—'} |`)
}
lines.push('')
const noText = entries.filter(({ ref }) => ref === null)
if (noText.length > 0) {
  lines.push('## Crates without a license file in their package')
  lines.push('')
  lines.push('These crates declare a license but ship no license file in the published package; the text lives in the upstream repository.')
  lines.push('')
  lines.push('| Crate | Version | License | Repository |')
  lines.push('| --- | --- | --- | --- |')
  for (const { pkg, spdx } of noText) {
    const repo = pkg.repository || pkg.homepage || `https://crates.io/crates/${pkg.name}`
    lines.push(`| ${pkg.name} | ${pkg.version} | ${spdx} | ${repo} |`)
  }
  lines.push('')
}
lines.push('## License texts')
lines.push('')
for (const { id, spdx, text, source } of appendix) {
  lines.push(`### ${id} — ${spdx}`)
  lines.push('')
  lines.push(`From ${source}.`)
  lines.push('')
  lines.push('```')
  lines.push(text)
  lines.push('```')
  lines.push('')
}

if (entries.length === 0) throw new Error('cargo metadata returned no third-party crates')
const result = `${lines.join('\n')}\n`
writeFileSync(out, result)
console.log(`Wrote ${relative(root, out)} (${entries.length} crates, ${appendix.length} distinct license texts)`)
